import { initializeApp } from "https://www.gstatic.com/firebasejs/13.0.0/firebase-app.js";
import { getAuth, onAuthStateChanged, signInWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/13.0.0/firebase-auth.js";
import { collection, doc, getDoc, getDocs, getFirestore, onSnapshot, serverTimestamp, setDoc } from "https://www.gstatic.com/firebasejs/13.0.0/firebase-firestore.js";

const $=selector=>document.querySelector(selector);
const config=window.MAUGAINZ_SITE_CONFIG?.firebase||{};
const app=initializeApp(config),auth=getAuth(app),db=getFirestore(app);
const previewMode=['127.0.0.1','localhost'].includes(location.hostname)&&new URLSearchParams(location.search).has('preview');
let accountRows=[],publicRows=[],users=[],searchText='',filter='all',unsubscribers=[];

const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const timestamp=value=>value?.toDate?.()?.getTime?.()||0;
const formatDate=value=>{const time=timestamp(value);return time?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(time):'Not yet'};
const age=value=>{const time=timestamp(value);if(!time)return'Awaiting check-in';const minutes=Math.floor((Date.now()-time)/60000);if(minutes<2)return'Now';if(minutes<60)return`${minutes}m ago`;const hours=Math.floor(minutes/60);if(hours<24)return`${hours}h ago`;const days=Math.floor(hours/24);return`${days}d ago`};
const statusFor=value=>{const time=timestamp(value),difference=Date.now()-time;if(!time)return{label:'Pending',className:''};if(difference<15*60*1000)return{label:'Online',className:'online'};if(difference<7*86400000)return{label:'Active',className:'recent'};return{label:'Inactive',className:''}};

function mergeUsers(){const map=new Map();for(const profile of publicRows)map.set(profile.id,{uid:profile.id,...profile});for(const account of accountRows)map.set(account.id,{...(map.get(account.id)||{uid:account.id}),...account,uid:account.id});users=[...map.values()].sort((a,b)=>(timestamp(b.lastSeen)||timestamp(b.createdAt))-(timestamp(a.lastSeen)||timestamp(a.createdAt)));render()}
function render(){const weekAgo=Date.now()-7*86400000;const known=users.filter(user=>timestamp(user.lastSeen));$('[data-total]').textContent=users.length;$('[data-active]').textContent=users.filter(user=>timestamp(user.lastSeen)>=weekAgo).length;$('[data-android]').textContent=known.filter(user=>user.platform==='android').length;$('[data-web]').textContent=known.filter(user=>user.platform==='web').length;const needle=searchText.trim().toLowerCase(),visible=users.filter(user=>{const matches=!needle||`${user.displayName||''} ${user.email||''} ${user.friendCode||''} ${user.uid}`.toLowerCase().includes(needle);if(!matches)return false;if(filter==='active')return timestamp(user.lastSeen)>=weekAgo;if(filter==='android'||filter==='web')return user.platform===filter;if(filter==='pending')return !timestamp(user.lastSeen);return true});$('[data-users]').innerHTML=visible.map(user=>{const status=statusFor(user.lastSeen),name=user.displayName||'MauGainZ athlete',email=user.email||'Email available after next sign-in',platform=user.platform||'Pending';return`<tr><td><div class="person"><span class="avatar">${esc(name.slice(0,1).toUpperCase())}</span><div><b>${esc(name)}</b><small>${esc(email)}</small><small>${esc(user.friendCode||user.uid)}</small></div></div></td><td><span class="status ${status.className}">${status.label}</span></td><td title="${esc(formatDate(user.lastSeen))}">${esc(age(user.lastSeen))}</td><td><span class="platform">${esc(platform)}</span></td><td>${esc(user.appVersion||'—')}</td><td class="number">${Number.isFinite(user.recipeCount)?user.recipeCount:'—'}</td><td class="number">${Number.isFinite(user.diaryEntryCount)?user.diaryEntryCount:'—'}</td><td class="number">${Number.isFinite(user.savedIngredientCount)?user.savedIngredientCount:'—'}</td></tr>`}).join('');$('[data-empty]').hidden=visible.length>0;$('[data-visible-count]').textContent=`${visible.length} user${visible.length===1?'':'s'}`}

function stopSubscriptions(){unsubscribers.forEach(unsubscribe=>unsubscribe());unsubscribers=[]}
async function ensureAdminProfile(user){const reference=doc(db,'accountProfiles',user.uid),snapshot=await getDoc(reference),name=user.displayName||user.email?.split('@')[0]||'Administrator';await setDoc(reference,{uid:user.uid,email:user.email||'',displayName:name,friendCode:user.uid.replace(/[^a-z0-9]/gi,'').slice(0,8).toUpperCase(),lastSeen:serverTimestamp(),platform:'web',appVersion:window.MAUGAINZ_SITE_CONFIG?.currentVersion||'web',...(!snapshot.exists()?{createdAt:serverTimestamp()}: {})},{merge:true})}
async function openAdmin(user){try{await Promise.all([getDocs(collection(db,'accountProfiles')),getDocs(collection(db,'publicProfiles'))]);await ensureAdminProfile(user);$('[data-auth]').hidden=true;$('[data-denied]').hidden=true;$('[data-admin]').hidden=false;$('[data-admin-email]').textContent=user.email||'Administrator';stopSubscriptions();unsubscribers=[onSnapshot(collection(db,'accountProfiles'),snapshot=>{accountRows=snapshot.docs.map(item=>({id:item.id,...item.data()}));mergeUsers()}),onSnapshot(collection(db,'publicProfiles'),snapshot=>{publicRows=snapshot.docs.map(item=>({id:item.id,...item.data()}));mergeUsers()})]}catch(error){console.error(error);$('[data-auth]').hidden=true;$('[data-admin]').hidden=true;$('[data-denied]').hidden=false}}
function openLogin(){stopSubscriptions();$('[data-auth]').hidden=false;$('[data-admin]').hidden=true;$('[data-denied]').hidden=true}

$('[data-login-form]').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.currentTarget),button=event.currentTarget.querySelector('button');$('[data-login-error]').textContent='';button.disabled=true;try{await signInWithEmailAndPassword(auth,String(data.get('email')||'').trim(),String(data.get('password')||''))}catch(error){$('[data-login-error]').textContent=String(error?.message||'Could not sign in.').replace(/^Firebase:\s*/i,'').replace(/\(auth\/.+?\)\.?/i,'').trim()}finally{button.disabled=false}};
$('[data-signout]').onclick=()=>signOut(auth);
$('[data-denied-signout]').onclick=()=>signOut(auth);
$('[data-search]').oninput=event=>{searchText=event.target.value;render()};
$('[data-filter]').onchange=event=>{filter=event.target.value;render()};
if(previewMode){const mockTime=milliseconds=>({toDate:()=>new Date(milliseconds)}),now=Date.now();accountRows=[{id:'preview-admin',uid:'preview-admin',displayName:'MauGainZ Owner',email:'owner@example.com',friendCode:'OWNER001',createdAt:mockTime(now-90*86400000),lastSeen:mockTime(now-3*60000),platform:'web',appVersion:'2.4.0',recipeCount:18,diaryEntryCount:142,savedIngredientCount:35},{id:'preview-phone',uid:'preview-phone',displayName:'Liam Power',email:'liam@example.com',friendCode:'LIAM0001',createdAt:mockTime(now-28*86400000),lastSeen:mockTime(now-2*86400000),platform:'android',appVersion:'2.4.0',recipeCount:9,diaryEntryCount:61,savedIngredientCount:22},{id:'preview-tablet',uid:'preview-tablet',displayName:'Noor Gains',email:'noor@example.com',friendCode:'NOOR0001',createdAt:mockTime(now-9*86400000),lastSeen:mockTime(now-10*86400000),platform:'android',appVersion:'2.3.1',recipeCount:4,diaryEntryCount:19,savedIngredientCount:8}];publicRows=[...accountRows,{id:'preview-pending',uid:'preview-pending',displayName:'New athlete',friendCode:'NEW00001',createdAt:mockTime(now-86400000)}];$('[data-loading]').hidden=true;$('[data-auth]').hidden=true;$('[data-admin]').hidden=false;$('[data-admin-email]').textContent='owner@example.com';mergeUsers()}else onAuthStateChanged(auth,user=>{$('[data-loading]').hidden=true;if(user)openAdmin(user);else openLogin()});
